    filter.push({ terms: { class_ids: options.definedClasses } });
  if (options.definedTypes)
    filter.push({ terms: { type: options.definedTypes } });
  if (options.type)
    filter.push({ term: { type: options.type } });
  if (options.includeTypes)
    filter.push({ terms: { type: options.includeTypes } });
  if (options.emptyType)
    filter.push({ bool: { should: [{ bool: { must_not: [{ exists: { field: "type" } }] } }, { term: { type: "" } }], minimum_should_match: 1 } });
  if (options.hasImage)
    filter.push({ term: { has_images: true } });
