        id: entity.id,
        name: entity.name,
        description: entity.description,
        aliases: entity.aliases,
        typeId: ontology.id,
        tags: [...new Map([...entity.tags, ...categoryTags].map((tag) => [key(tag), tag])).values()],
        images: entity.images,
        videos: entity.videos,
        pdf: entity.pdf,
        link: entity.link,
