function getProjectByIdentifier(identifier) {
  const raw = (identifier ?? "").toString().trim();
  if (!raw)
    return null;
  const byId = /^\d+$/.test(raw) ? queryGetSafe("SELECT * FROM projects WHERE id = ? LIMIT 1", Number.parseInt(raw, 10)) : null;
  if (byId)
    return byId;
  return queryGetSafe("SELECT * FROM projects WHERE name = ? LIMIT 1", raw) || queryGetSafe("SELECT * FROM projects WHERE lower(title) = lower(?) LIMIT 1", raw);
}
function rewriteImportedEntityReferences(value, idMap) {
  if (Array.isArray(value)) {
    return value.map((item) => rewriteImportedEntityReferences(item, idMap));
  }
  if (!value || typeof value !== "object") {
    return value;
  }
  const next = { ...value };
  const candidates = ["id", "entity-id", "entity_id", "entityId"];
  for (const key3 of candidates) {
    const current = next[key3];
    if (!current && current !== 0)
      continue;
    const raw = current.toString().trim();
    if (!raw)
      continue;
    const normalized = raw.startsWith("entity/") ? raw.slice(7) : raw;
    const mapped = idMap.get(normalized);
    if (!mapped)
      continue;
    next[key3] = raw.startsWith("entity/") ? `entity/${mapped}` : mapped;
  }
  if (next.value && typeof next.value === "object") {
    next.value = rewriteImportedEntityReferences(next.value, idMap);
  }
  return next;
}
function importLegacyProjectKnowledge() {
  const projects = queryAllSafe("SELECT id, name, title FROM projects WHERE name IS NOT NULL AND name <> ''");
  for (const project of projects) {
    const projectId = Number(project.id || 0);
    const projectSlug = (project.name || "").toString().trim();
    if (!projectId || !projectSlug)
      continue;
    const existingCount = queryGetSafe("SELECT COUNT(*) AS count FROM nodes WHERE project_id = ?", projectId);
    if (Number(existingCount?.count || 0) > 0)
      continue;
    const legacyPath = resolve5(ROOT_DATA_DIR, `${projectSlug}.sqlite`);
    if (!existsSync2(legacyPath) || legacyPath === APP_DB_PATH)
      continue;
    let legacyDb = null;
    try {
      legacyDb = new Database2(legacyPath, { readonly: true });
      const legacyTables = legacyDb.query("SELECT name FROM sqlite_master WHERE type = 'table'").all();
      const hasNodes = legacyTables.some((row) => row?.name === "nodes");
      if (!hasNodes)
        continue;
      const legacyNodes = legacyDb.query("SELECT * FROM nodes").all();
      if (!legacyNodes.length)
        continue;
      const idMap = new Map;
      for (const row of legacyNodes) {
        const oldId = (row.id ?? "").toString();
        if (!oldId)
          continue;
        idMap.set(oldId, `${projectSlug}:${oldId}`);
      }
      const legacyProperties = legacyTables.some((row) => row?.name === "properties") ? legacyDb.query("SELECT * FROM properties").all() : [];
      for (const row of legacyProperties) {
        try {
          appDb.run("INSERT OR IGNORE INTO properties (id, name, datatype, valuetype, types, description, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, COALESCE(?, CURRENT_TIMESTAMP), COALESCE(?, CURRENT_TIMESTAMP))", [
            row.id,
            row.name || row.id,
            row.datatype || "string",
            row.valuetype || null,
            row.types || "[]",
            row.description || "",
            row.created_at || null,
            row.updated_at || null
          ]);
        } catch {}
      }
      const legacyClasses = legacyTables.some((row) => row?.name === "classes") ? legacyDb.query("SELECT * FROM classes").all() : [];
      for (const row of legacyClasses) {
        try {
          appDb.run("INSERT OR IGNORE INTO classes (id, name, description, parent_id, color, sort_order, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, COALESCE(?, CURRENT_TIMESTAMP), COALESCE(?, CURRENT_TIMESTAMP))", [
            row.id,
            row.name || row.id,
            row.description || "",
            row.parent_id || null,
            row.color || null,
            row.sort_order || null,
            row.created_at || null,
            row.updated_at || null
          ]);
        } catch {}
      }
      for (const row of legacyNodes) {
        const mappedId = idMap.get((row.id ?? "").toString());
        if (!mappedId)
          continue;
        appDb.run("INSERT OR IGNORE INTO nodes (id, name, type, description, wiki_md, aliases, tags, data, project_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, COALESCE(?, CURRENT_TIMESTAMP), COALESCE(?, CURRENT_TIMESTAMP))", [
          mappedId,
          row.name || mappedId,
          row.type || "entity",
          row.description || "",
          row.wiki_md || "",
          row.aliases || "[]",
          row.tags || "[]",
          row.data || "{}",
          projectId,
          row.created_at || null,
          row.updated_at || null
        ]);
      }
      const legacyAttributes = legacyTables.some((row) => row?.name === "attributes") ? legacyDb.query("SELECT * FROM attributes").all() : [];
      for (const row of legacyAttributes) {
        const mappedNodeId = idMap.get((row.node_id ?? "").toString());
        if (!mappedNodeId)
          continue;
        let nextValue = row.value;
        if ((row.datatype || "").trim() === "wikibase-entityid" && row.value) {
          try {
            nextValue = JSON.stringify(rewriteImportedEntityReferences(JSON.parse(row.value), idMap));
          } catch {}
        }
        const attrId = `${projectSlug}:${row.id}`;
        appDb.run("INSERT OR IGNORE INTO attributes (id, node_id, key, value, datatype, created_at) VALUES (?, ?, ?, ?, ?, COALESCE(?, CURRENT_TIMESTAMP))", [
          attrId,
          mappedNodeId,
          row.key,
          nextValue,
          row.datatype || "string",
          row.created_at || null
        ]);
      }
      const legacyEntityClasses = legacyTables.some((row) => row?.name === "entity_classes") ? legacyDb.query("SELECT * FROM entity_classes").all() : [];
      for (const row of legacyEntityClasses) {
        const mappedEntityId = idMap.get((row.entity_id ?? "").toString());
        if (!mappedEntityId)
          continue;
        appDb.run("INSERT OR IGNORE INTO entity_classes (entity_id, class_id, created_at) VALUES (?, ?, COALESCE(?, CURRENT_TIMESTAMP))", [mappedEntityId, row.class_id, row.created_at || null]);
      }
    } catch (err) {
      console.warn("importLegacyProjectKnowledge failed", projectSlug, err);
    } finally {
      try {
        legacyDb?.close();
      } catch {}
    }
  }
}
function migrateLegacyAnyStore() {
  if (!existsSync2(LEGACY_ANY_STORE_DB_PATH))
    return;
  const legacyAny = new Database2(LEGACY_ANY_STORE_DB_PATH, { readonly: true });
  const userIdMap = new Map;
  const projectIdMap = new Map;
  try {
    const legacyTables = new Set(legacyAny.query("SELECT name FROM sqlite_master WHERE type = 'table'").all().map((row) => row.name));
    const readLegacyRows = (table, sql) => legacyTables.has(table) ? legacyAny.query(sql).all() : [];
    const users = readLegacyRows("users", "SELECT id, username, password, avatar, is_admin, created_at FROM users");
    for (const row of users) {
      const username = (row.username || "").toString().trim().toLowerCase();
      if (!username)
        continue;
      const existing = queryGetSafe("SELECT id FROM users WHERE username = ? LIMIT 1", username);
      if (existing?.id) {
        userIdMap.set(Number(row.id), Number(existing.id));
        appDb.run("UPDATE users SET avatar = COALESCE(NULLIF(avatar, ''), ?), is_admin = MAX(COALESCE(is_admin, 0), ?), password = COALESCE(password, ?), password_salt = COALESCE(password_salt, ?), password_hash = COALESCE(password_hash, ?), updated_at = CURRENT_TIMESTAMP WHERE id = ?", [
          row.avatar || "",
          row.is_admin ? 1 : 0,
          row.password || "",
          String(row.password || "").split("$")[0] || "",
          String(row.password || "").split("$")[1] || "",
          existing.id
        ]);
        continue;
      }
      const password = (row.password || "").toString();
      const [salt, hash] = password.includes("$") ? password.split("$", 2) : ["", ""];
      appDb.run("INSERT INTO users (id, username, display_name, password, password_hash, password_salt, avatar, is_admin, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [
        row.id,
        username,
        username,
        password,
        hash || "",
        salt || "",
        row.avatar || "",
        row.is_admin ? 1 : 0,
        row.created_at || Date.now(),
        row.created_at || Date.now()
      ]);
      userIdMap.set(Number(row.id), Number(row.id));
    }
    const products = readLegacyRows("products", "SELECT id, name, description, logo, theme_color, tags, created_at, updated_at FROM products");
    for (const row of products) {
      const title = (row.name || "").toString().trim();
      if (!title)
        continue;
      const existing = queryGetSafe("SELECT id FROM projects WHERE title = ? LIMIT 1", title) || queryGetSafe("SELECT id FROM projects WHERE name = ? LIMIT 1", title);
      if (existing?.id) {
        projectIdMap.set(Number(row.id), Number(existing.id));
        appDb.run(`UPDATE projects SET description = COALESCE(NULLIF(description, ''), ?), image = COALESCE(NULLIF(image, ''), ?), theme_color = COALESCE(theme_color, ?), tags = COALESCE(tags, ?), file = COALESCE(NULLIF(file, ''), '${APP_DB_FILENAME}'), updated_at = COALESCE(updated_at, ?) WHERE id = ?`, [
          row.description || "",
          row.logo || "",
          row.theme_color || "#ff7a2b",
          row.tags || "[]",
          row.updated_at || Date.now(),
          existing.id
        ]);
        continue;
      }
      const baseName = slugifyProjectName(title, `product-${row.id}`);
      const projectName = ensureUniqueProjectName(baseName);
      appDb.run("INSERT INTO projects (id, name, file, title, description, image, theme_color, tags, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [
        row.id,
        projectName,
        APP_DB_FILENAME,
        title,
        row.description || "",
        row.logo || "",
        row.theme_color || "#ff7a2b",
        row.tags || "[]",
        row.created_at || Date.now(),
        row.updated_at || Date.now()
      ]);
      projectIdMap.set(Number(row.id), Number(row.id));
    }
    const links = readLegacyRows("links", "SELECT * FROM links");
    for (const row of links) {
      appDb.run("INSERT OR IGNORE INTO links (id, name, url, image, tags, description, owner_id, source, screenshots, short_description, first_comment, approved, approved_by, approved_at, featured, product_id, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)", [
        row.id,
        row.name,
        row.url,
        row.image || "",
        row.tags || "[]",
        row.description || "",
        row.owner_id ? userIdMap.get(Number(row.owner_id)) || null : null,
        row.source || "",
        row.screenshots || "[]",
        row.short_description || "",
        row.first_comment || "",
        row.approved ? 1 : 0,
        row.approved_by ? userIdMap.get(Number(row.approved_by)) || null : null,
        row.approved_at || null,
        row.featured ? 1 : 0,
        row.product_id ? projectIdMap.get(Number(row.product_id)) || null : null,
        row.created_at || Date.now(),
        row.updated_at || Date.now()
      ]);
    }
    const comments = readLegacyRows("comments", "SELECT * FROM comments");
    for (const row of comments) {
      appDb.run("INSERT OR IGNORE INTO comments (id, link_id, user_id, username, content, parent_id, created_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [
        row.id,
        row.link_id,
        row.user_id ? userIdMap.get(Number(row.user_id)) || null : null,
        row.username || "",
        row.content || "",
        row.parent_id || null,
        row.created_at || Date.now()
      ]);
    }
    const linkLikes = readLegacyRows("link_likes", "SELECT link_id, user_id FROM link_likes");
    for (const row of linkLikes) {
      const userId = userIdMap.get(Number(row.user_id));
      if (!userId)
        continue;
      appDb.run("INSERT OR IGNORE INTO link_likes (link_id, user_id) VALUES (?, ?)", [row.link_id, userId]);
    }
    const commentLikes = readLegacyRows("comment_likes", "SELECT comment_id, user_id FROM comment_likes");
    for (const row of commentLikes) {
      const userId = userIdMap.get(Number(row.user_id));
      if (!userId)
        continue;
      appDb.run("INSERT OR IGNORE INTO comment_likes (comment_id, user_id) VALUES (?, ?)", [row.comment_id, userId]);
    }
    const sessions = readLegacyRows("sessions", "SELECT id, user_id, expires_at FROM sessions");
    for (const row of sessions) {
      const userId = userIdMap.get(Number(row.user_id));
      if (!userId)
        continue;
      const user = queryGetSafe("SELECT username FROM users WHERE id = ? LIMIT 1", userId);
      appDb.run("INSERT OR IGNORE INTO sessions (id, token, username, user_id, created_at, expires_at) VALUES (?, ?, ?, ?, CURRENT_TIMESTAMP, ?)", [row.id, row.id, user?.username || null, userId, row.expires_at]);
    }
    const settingsRows = readLegacyRows("settings", "SELECT key, value FROM settings");
    for (const row of settingsRows) {
      if (row.key === "currentProduct") {
        try {
          const currentProduct = JSON.parse(row.value || "null");
          if (currentProduct?.id) {
            const mappedId = projectIdMap.get(Number(currentProduct.id));
            if (mappedId) {
              appDb.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", [
                row.key,
                JSON.stringify({
                  ...currentProduct,
                  id: mappedId
                })
              ]);
              continue;
            }
          }
        } catch {}
      }
      appDb.run("INSERT OR IGNORE INTO settings (key, value) VALUES (?, ?)", [
        row.key,
        row.value
      ]);
    }
  } catch (error) {
    console.warn("Failed to migrate legacy any-store data:", error);
  } finally {
    legacyAny.close();
  }
}
function migrateLegacyAdminDatabase() {
  if (!existsSync2(LEGACY_ADMIN_DB_PATH))
    return;
  const legacyAdmin = new Database2(LEGACY_ADMIN_DB_PATH, { readonly: true });
  try {
    const projects = legacyAdmin.query("SELECT name, file, title, description, image, created_at, updated_at FROM projects").all();
    for (const row of projects) {
      const name = (row.name || "").toString().trim();
      if (!name)
        continue;
      appDb.run("INSERT OR IGNORE INTO projects (name, file, title, description, image, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?)", [
        name,
        row.file === "shared.sqlite" ? APP_DB_FILENAME : row.file || APP_DB_FILENAME,
        row.title || name,
        row.description || "",
        row.image || "",
        row.created_at || new Date().toISOString(),
        row.updated_at || new Date().toISOString()
      ]);
    }
    const users = legacyAdmin.query("SELECT username, display_name, password_hash, password_salt, avatar, created_at, updated_at FROM users").all();
    for (const row of users) {
      const username = (row.username || "").toString().trim().toLowerCase();
      if (!username)
        continue;
      appDb.run("INSERT OR IGNORE INTO users (username, display_name, password, password_hash, password_salt, avatar, created_at, updated_at) VALUES (?, ?, ?, ?, ?, ?, ?, ?)", [
        username,
        row.display_name || username,
        row.password_salt && row.password_hash ? `${row.password_salt}$${row.password_hash}` : null,
        row.password_hash || "",
        row.password_salt || "",
        row.avatar || "",
        row.created_at || new Date().toISOString(),
        row.updated_at || new Date().toISOString()
      ]);
    }
    const sessions = legacyAdmin.query("SELECT token, username, created_at, expires_at FROM sessions").all();
    for (const row of sessions) {
      const user = queryGetSafe("SELECT id FROM users WHERE username = ? LIMIT 1", row.username);
      appDb.run("INSERT OR IGNORE INTO sessions (id, token, username, user_id, created_at, expires_at) VALUES (?, ?, ?, ?, ?, ?)", [
        row.token,
        row.token,
        row.username,
        user?.id || null,
        row.created_at || new Date().toISOString(),
        row.expires_at || null
      ]);
    }
  } catch (error) {
    console.warn("Failed to migrate legacy admin data:", error);
  } finally {
    legacyAdmin.close();
  }
}
function migrateLegacyKnowledgeGraphDatabase() {
  if (!existsSync2(LEGACY_KB_DB_PATH))
    return;
  const legacyKb = new Database2(LEGACY_KB_DB_PATH, { readonly: true });
  try {
    const tableCopies = [
      {
        name: "nodes",
        columns: "id, name, type, description, wiki_md, aliases, tags, data, pdf, created_at, updated_at"
      },
      {
        name: "attributes",
        columns: "id, node_id, key, value, datatype, created_at"
      },
      {
        name: "entity_classes",
        columns: "entity_id, class_id, created_at"
      },
      {
        name: "class_properties",
        columns: "class_id, property_id, created_at"
      },
      {
        name: "property_properties",
        columns: "parent_property_id, child_property_id, created_at"
      },
      {
        name: "properties",
        columns: "id, name, datatype, valuetype, description, created_at, updated_at"
      },
      {
        name: "classes",
        columns: "id, name, description, parent_id, color, sort_order, created_at, updated_at"
      }
    ];
    for (const table of tableCopies) {
      const rows = legacyKb.query(`SELECT ${table.columns} FROM ${table.name}`).all();
      for (const row of rows) {
        const values = table.columns.split(",").map((column) => {
          const key3 = column.trim();
          return row[key3];
        });
        appDb.run(`INSERT OR IGNORE INTO ${table.name} (${table.columns}) VALUES (${table.columns.split(",").map(() => "?").join(", ")})`, values);
      }
    }
  } catch (error) {
    console.warn("Failed to migrate legacy knowledge graph data:", error);
  } finally {
    legacyKb.close();
  }
}
function migrateLegacyDatabases() {
  const migrated = queryGetSafe("SELECT value FROM settings WHERE key = ? LIMIT 1", "__shared_data_migrated_v1__");
  if (migrated?.value === "1")
    return;
  migrateLegacyAnyStore();
  migrateLegacyAdminDatabase();
  migrateLegacyKnowledgeGraphDatabase();
  appDb.run("INSERT OR REPLACE INTO settings (key, value) VALUES (?, ?)", [
    "__shared_data_migrated_v1__",
    "1"
  ]);
}
function copyDirectoryIntoSharedUploads(sourceDir, relativeDir = "") {
  if (!existsSync2(sourceDir))
    return;
  const entries = readdirSync(sourceDir, { withFileTypes: true });
  for (const entry of entries) {
    const nextRelative = relativeDir ? join(relativeDir, entry.name) : entry.name;
    const sourcePath = resolve5(sourceDir, entry.name);
    const targetPath = resolve5(APP_UPLOADS_DIR, nextRelative);
    if (entry.isDirectory()) {
      mkdirSync4(targetPath, { recursive: true });
      copyDirectoryIntoSharedUploads(sourcePath, nextRelative);
      continue;
    }
    try {
      const sourceStat = statSync(sourcePath);
      if (!sourceStat.isFile())
        continue;
      if (!existsSync2(resolve5(targetPath, ".."))) {
        mkdirSync4(resolve5(targetPath, ".."), { recursive: true });
      }
      if (!existsSync2(targetPath)) {
        copyFileSync(sourcePath, targetPath);
      }
    } catch {}
  }
}
function copyDirectoryIntoRootData(sourceDir, relativeDir = "") {
  if (!existsSync2(sourceDir))
    return;
  const entries = readdirSync(sourceDir, { withFileTypes: true });
  for (const entry of entries) {
    const nextRelative = relativeDir ? join(relativeDir, entry.name) : entry.name;
    const sourcePath = resolve5(sourceDir, entry.name);
    const targetPath = resolve5(ROOT_DATA_DIR, nextRelative);
    if (entry.isDirectory()) {
      mkdirSync4(targetPath, { recursive: true });
      copyDirectoryIntoRootData(sourcePath, nextRelative);
      continue;
    }
    try {
      const sourceStat = statSync(sourcePath);
      if (!sourceStat.isFile())
        continue;
      if (!existsSync2(resolve5(targetPath, ".."))) {
        mkdirSync4(resolve5(targetPath, ".."), { recursive: true });
      }
      if (!existsSync2(targetPath)) {
        copyFileSync(sourcePath, targetPath);
      }
    } catch {}
  }
}
function migrateLegacyDataFilesToRoot() {
  if (existsSync2(OLD_SHARED_DB_PATH) && !existsSync2(APP_DB_PATH)) {
    try {
      copyFileSync(OLD_SHARED_DB_PATH, APP_DB_PATH);
    } catch {}
  }
  if (existsSync2(OLD_APP_DB_PATH) && !existsSync2(APP_DB_PATH)) {
    try {
      copyFileSync(OLD_APP_DB_PATH, APP_DB_PATH);
    } catch {}
  }
  copyDirectoryIntoRootData(OLD_KNOWLEDGE_GRAPH_DATA_DIR);
  copyDirectoryIntoRootData(OLD_ANY_STORE_DATA_DIR);
}
function migrateLegacyUploads() {
  copyDirectoryIntoSharedUploads(OLD_SHARED_UPLOADS_DIR);
  copyDirectoryIntoSharedUploads(LEGACY_ANY_STORE_UPLOADS_DIR);
  copyDirectoryIntoSharedUploads(LEGACY_KNOWLEDGE_GRAPH_UPLOADS_DIR);
}
function cleanupPlaceholderProjects() {
  try {
    const sharedProject = queryGetSafe("SELECT id FROM projects WHERE name = 'shared' LIMIT 1");
    if (sharedProject?.id) {
      const sharedNodeIds = queryAllSafe("SELECT id FROM nodes WHERE project_id = ?", sharedProject.id).map((row) => row.id);
      if (sharedNodeIds.length) {
        const placeholders = sharedNodeIds.map(() => "?").join(",");
        appDb.run(`DELETE FROM attributes WHERE node_id IN (${placeholders})`, sharedNodeIds);
        appDb.run(`DELETE FROM entity_classes WHERE entity_id IN (${placeholders})`, sharedNodeIds);
        appDb.run(`DELETE FROM nodes WHERE id IN (${placeholders})`, sharedNodeIds);
      }
      appDb.run("DELETE FROM projects WHERE id = ?", [sharedProject.id]);
    }
    appDb.run(`DELETE FROM projects
       WHERE name = 'shared'
         AND (title IS NULL OR title = '' OR title = 'shared')
         AND (description IS NULL OR description = '')
         AND (image IS NULL OR image = '')
         AND NOT EXISTS (SELECT 1 FROM links WHERE product_id = projects.id LIMIT 1)`);
    const orphanSharedNodeIds = queryAllSafe(`SELECT id
       FROM nodes
       WHERE id LIKE 'shared:%'
         OR (project_id IS NOT NULL AND project_id NOT IN (SELECT id FROM projects))`).map((row) => row.id);
    if (orphanSharedNodeIds.length) {
      const placeholders = orphanSharedNodeIds.map(() => "?").join(",");
      appDb.run(`DELETE FROM attributes WHERE node_id IN (${placeholders})`, orphanSharedNodeIds);
      appDb.run(`DELETE FROM entity_classes WHERE entity_id IN (${placeholders})`, orphanSharedNodeIds);
      appDb.run(`DELETE FROM nodes WHERE id IN (${placeholders})`, orphanSharedNodeIds);
    }
    appDb.run(`UPDATE projects
       SET file = '${APP_DB_FILENAME}'`);
  } catch {}
}
async function hashPassword(password, salt) {
  try {
    const s = salt || crypto.randomUUID().slice(0, 8);
    const enc = new TextEncoder;
    const data = enc.encode(s + password);
    const buf = await crypto.subtle.digest("SHA-256", data);
    const arr = Array.from(new Uint8Array(buf));
    const hex = arr.map((b2) => b2.toString(16).padStart(2, "0")).join("");
    return { salt: s, hash: hex };
  } catch {
    try {
      const c = __require("crypto");
      const s = salt || c.randomBytes(4).toString("hex");
      const h = c.createHash("sha256").update(s + password).digest("hex");
      return { salt: s, hash: h };
    } catch {
      return { salt: salt || "", hash: "" };
    }
  }
}
function initializeKnowledgeBaseDatabase() {
  if (enterpriseKnowledgeEnabled()) {
    ensureSharedTables();
    return;
  }
  migrateLegacyDataFilesToRoot();
  ensureSharedTables();
  migrateLegacyDatabases();
  importLegacyProjectKnowledge();
  migrateLegacyUploads();
  cleanupPlaceholderProjects();
  repairLegacyClonedEntityIds(appDb);
}
function switchDatabase(_filename) {
  db = createKnowledgeDatabase(appDb);
  adminDb = appDb;
  ensureSharedTables();
}
initializeKnowledgeBaseDatabase();
if (!enterpriseKnowledgeEnabled())
  ensureKnowledgeAccessSchema(appDb);
ensureApplicationSchema(appDb);
ensureDefaultApplication(appDb);

// src/server/initial-admin.ts
var PASSWORD_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%_-";
function generateInitialAdminPassword(length = 20) {
  const size = Math.max(16, Math.floor(length));
  const bytes = new Uint8Array(size);
  crypto.getRandomValues(bytes);
  return Array.from(bytes, (value) => PASSWORD_ALPHABET[value % PASSWORD_ALPHABET.length]).join("");
}
async function ensureInitialAdminAccount(database, passwordHasher, passwordFactory = generateInitialAdminPassword) {
  const count = Number(database.query("SELECT COUNT(*) AS count FROM users").get()?.count || 0);
  if (count > 0)
    return null;
  const username = "admin";
  const password = passwordFactory();
  const passwordHash = await passwordHasher(password);
  if (!passwordHash.hash || !passwordHash.salt) {
    throw new Error("\u65E0\u6CD5\u751F\u6210\u521D\u59CB\u7BA1\u7406\u5458\u5BC6\u7801\u54C8\u5E0C");
  }
  database.run("BEGIN IMMEDIATE");
  try {
    const transactionalCount = Number(database.query("SELECT COUNT(*) AS count FROM users").get()?.count || 0);
    if (transactionalCount > 0) {
      database.run("ROLLBACK");
      return null;
    }
    database.run(`INSERT INTO users
       (username, display_name, password_hash, password_salt, role, status, is_admin)
       VALUES (?, ?, ?, ?, 'admin', 'active', 1)`, [username, "\u7CFB\u7EDF\u7BA1\u7406\u5458", passwordHash.hash, passwordHash.salt]);
    database.run(`INSERT OR IGNORE INTO user_roles (user_id, role_id)
       SELECT u.id, r.id
       FROM users u
       JOIN roles r ON r.code = 'super_admin'
       WHERE u.username = ?`, [username]);
    database.run("COMMIT");
    return { username, password };
  } catch (error) {
    try {
      database.run("ROLLBACK");
    } catch {}
    throw error;
  }
}

// src/server/user-profile.ts
var json2 = (body, init = {}) => Response.json(body, { ...init, headers: { "Cache-Control": "no-store" } });
function createUserProfileHandler(db2, getUser, activity) {
  ensureAccountActivitySchema(db2);
  const hasTable = (name) => Boolean(db2.query("SELECT 1 FROM sqlite_master WHERE type='table' AND name=?").get(name));
  const tableColumns = (name) => new Set(hasTable(name) ? db2.query(`PRAGMA table_info(${name})`).all().map((column) => String(column.name || "")) : []);
  const projectColumns = new Set(db2.query("PRAGMA table_info(projects)").all().map((column) => String(column.name || "")));
  const projectImageSelect = projectColumns.has("image") ? "p.image" : "'' AS image";
  const projectThemeSelect = projectColumns.has("theme_color") ? "p.theme_color" : "'' AS theme_color";
  return async (req, url, method) => {
    if (url.pathname !== "/api/account/profile")
      return null;
    if (method !== "GET")
      return json2({ error: "\u4E0D\u652F\u6301\u7684\u64CD\u4F5C" }, { status: 405 });
    const user = getUser(req);
    if (!user || user.id <= 0 || user.status === "disabled")
      return json2({ error: "\u8BF7\u5148\u767B\u5F55" }, { status: 401 });
    const section = url.searchParams.get("section") || "summary";
    if (!["summary", "applications", "knowledge", "likes", "favorites", "history", "comments"].includes(section))
      return json2({ error: "\u672A\u77E5\u7684\u8BB0\u5F55\u7C7B\u578B" }, { status: 400 });
    const requestedPage = Number(url.searchParams.get("page") || 1);
    if (!Number.isSafeInteger(requestedPage) || requestedPage < 1)
      return json2({ error: "\u9875\u7801\u65E0\u6548" }, { status: 400 });
    const appWhere = "p.name <> 'shared' AND (p.owner_user_id=? OR EXISTS (SELECT 1 FROM application_members m WHERE m.project_id=p.id AND m.user_id=?))";
    const nodeWhere = `(n.owner_user_id=? OR EXISTS (SELECT 1 FROM knowledge_maintainers m WHERE m.node_id=n.id AND m.user_id=?)) AND ${accessCondition(user, "n")}`;
    const count = (sql, params2) => Number(db2.query(sql).get(...params2)?.total || 0);
    const relatedParams = [user.id, user.id];
    if (section === "summary") {
      const basic = db2.query("SELECT id,username,display_name,avatar,email,phone,status,created_at,last_login_at FROM users WHERE id=?").get(user.id);
      if (!basic)
        return json2({ error: "\u8D26\u53F7\u4E0D\u5B58\u5728" }, { status: 401 });
      const allPermissions = db2.query("SELECT code,name,module FROM permissions ORDER BY module,code").all();
      const unrestricted = user.role === "admin" || user.permissions?.includes("*");
      const activityYear = new Date().getFullYear();
      const activityCounts = new Map;
      const addActivity = (value) => {
        const date = String(value || "").match(/^\d{4}-\d{2}-\d{2}/)?.[0] || "";
        if (!date || !date.startsWith(`${activityYear}-`))
          return;
        activityCounts.set(date, (activityCounts.get(date) || 0) + 1);
      };
      if (projectColumns.has("created_at")) {
        db2.query("SELECT created_at FROM projects WHERE owner_user_id=?").all(user.id).forEach((row) => addActivity(row.created_at));
      }
      const nodeColumns = tableColumns("nodes");
      if (nodeColumns.has("updated_at")) {
        db2.query(`SELECT n.updated_at FROM nodes n WHERE ${nodeWhere}`).all(...relatedParams).forEach((row) => addActivity(row.updated_at));
      }
      for (const table of ["knowledge_likes", "knowledge_favorites", "knowledge_comments"]) {
        const columns2 = tableColumns(table);
        if (!columns2.has("user_id") || !columns2.has("created_at"))
          continue;
        db2.query(`SELECT created_at FROM ${table} WHERE user_id=?`).all(user.id).forEach((row) => addActivity(row.created_at));
      }
      const activityDays = [...activityCounts].sort(([left], [right]) => left.localeCompare(right)).map(([date, count2]) => ({ date, count: count2 }));
      let personalCounts = null;
      if (activity) {
        try {
          personalCounts = await activity.counts(user);
        } catch {
          return json2({ error: "\u4E2A\u4EBA\u8BB0\u5F55\u52A0\u8F7D\u5931\u8D25\uFF0C\u8BF7\u91CD\u8BD5" }, { status: 503 });
        }
      }
      return json2({
        user: { id: basic.id, username: basic.username, displayName: basic.display_name || basic.username, avatar: basic.avatar || "", email: basic.email || "", phone: basic.phone || "", status: basic.status || "active", createdAt: basic.created_at, lastLoginAt: basic.last_login_at, role: user.role, dataScope: user.dataScope || "own" },
        roles: (user.roles || []).map((role) => ({ code: role.code, name: role.name, dataScope: role.data_scope })),
        permissions: allPermissions.filter((permission) => unrestricted || user.permissions?.includes(permission.code)),
        unrestricted,
        counts: {
          applications: count(`SELECT COUNT(*) AS total FROM projects p WHERE ${appWhere}`, relatedParams),
          knowledge: count(`SELECT COUNT(*) AS total FROM nodes n WHERE ${nodeWhere}`, relatedParams),
          likes: personalCounts?.likes ?? count("SELECT COUNT(*) AS total FROM knowledge_likes WHERE user_id=?", [user.id]),
          favorites: personalCounts?.favorites ?? count("SELECT COUNT(*) AS total FROM knowledge_favorites WHERE user_id=?", [user.id]),
          history: personalCounts?.history ?? count("SELECT COUNT(*) AS total FROM account_knowledge_activity WHERE user_id=? AND kind='history'", [user.id]),
          comments: count("SELECT COUNT(*) AS total FROM knowledge_comments WHERE user_id=?", [user.id])
        },
        activity: { year: activityYear, total: activityDays.reduce((sum, item) => sum + item.count, 0), days: activityDays }
      });
    }
    if (activity && (section === "history" || section === "favorites" || section === "likes" && activity.enterprise)) {
      try {
        const records = await activity.records(user, section), pageSize2 = 20;
        const page2 = Math.min(requestedPage, Math.max(1, Math.ceil(records.length / pageSize2)));
        return json2({ section, items: records.slice((page2 - 1) * pageSize2, page2 * pageSize2), total: records.length, page: page2, pageSize: pageSize2 });
      } catch {
        return json2({ error: "\u4E2A\u4EBA\u8BB0\u5F55\u52A0\u8F7D\u5931\u8D25\uFF0C\u8BF7\u91CD\u8BD5" }, { status: 503 });
      }
    }
    let total, query, params;
    if (section === "applications") {
      total = count(`SELECT COUNT(*) AS total FROM projects p WHERE ${appWhere}`, relatedParams);
      query = `SELECT p.id,p.name AS slug,p.title,p.description,${projectImageSelect},${projectThemeSelect},p.created_at,CASE WHEN p.owner_user_id=? THEN 'owner' ELSE 'maintainer' END AS relationship FROM projects p WHERE ${appWhere} ORDER BY p.created_at DESC,p.id DESC`;
      params = [user.id, ...relatedParams];
    } else if (section === "knowledge") {
      total = count(`SELECT COUNT(*) AS total FROM nodes n WHERE ${nodeWhere}`, relatedParams);
      query = `SELECT n.id,n.name,n.type,n.visibility,n.updated_at,p.name AS project_slug,p.title AS project_title,CASE WHEN n.owner_user_id=? THEN 'owner' ELSE 'maintainer' END AS relationship FROM nodes n LEFT JOIN projects p ON p.id=n.project_id WHERE ${nodeWhere} ORDER BY n.updated_at DESC,n.id DESC`;
      params = [user.id, ...relatedParams];
    } else if (section === "history") {
      total = count("SELECT COUNT(*) AS total FROM account_knowledge_activity WHERE user_id=? AND kind='history'", [user.id]);
      query = `SELECT h.created_at,n.id,n.name,n.type,p.name AS project_slug,p.title AS project_title FROM account_knowledge_activity h LEFT JOIN nodes n ON n.id=h.node_id AND n.project_id=h.project_id AND ${accessCondition(user, "n")} LEFT JOIN projects p ON p.id=h.project_id WHERE h.user_id=? AND h.kind='history' ORDER BY h.created_at DESC,h.node_id`;
      params = [user.id];
    } else {
      const table = { likes: "knowledge_likes", favorites: "knowledge_favorites", comments: "knowledge_comments" }[section];
      total = count(`SELECT COUNT(*) AS total FROM ${table} WHERE user_id=?`, [user.id]);
      const comment = section === "comments";
      query = `SELECT ${comment ? "h.id AS record_id,CASE WHEN n.id IS NOT NULL THEN h.content ELSE NULL END AS content," : ""} h.created_at,n.id,n.name,n.type,p.name AS project_slug,p.title AS project_title FROM ${table} h LEFT JOIN nodes n ON n.id=CASE WHEN h.knowledge_id LIKE 'entity/%' THEN substr(h.knowledge_id,8) ELSE h.knowledge_id END AND ${accessCondition(user, "n")} LEFT JOIN projects p ON p.id=n.project_id WHERE h.user_id=? ORDER BY h.created_at DESC,${comment ? "h.id" : "h.knowledge_id"} DESC`;
      params = [user.id];
    }
    const pageSize = 20, page = Math.min(requestedPage, Math.max(1, Math.ceil(total / pageSize)));
    const items = db2.query(`${query} LIMIT ? OFFSET ?`).all(...params, pageSize, (page - 1) * pageSize);
    return json2({ section, items, total, page, pageSize });
  };
}

// src/server/random-knowledge.ts
function randomKnowledge(db2, projectId, currentId, recent = []) {
  const current = currentId.replace(/^entity\//, "");
  const excluded = [...new Set([current, ...recent.map((id) => id.replace(/^entity\//, ""))].filter(Boolean))].slice(0, 51);
  const query = (ids) => db2.query(`SELECT * FROM nodes WHERE project_id IS ? ${ids.length ? `AND id NOT IN (${ids.map(() => "?").join(",")})` : ""} ORDER BY RANDOM() LIMIT 1`).get(projectId, ...ids);
  return query(excluded) || (excluded.length > 1 ? query(current ? [current] : []) : null);
}

