    const source = String(text || "").replace(/\uFF20/g, "@");
    if (!source)
      return [];
    const labels = [];
    const seen = new Set;
    const pushLabel = (raw) => {
      const label = String(raw || "").trim();
      if (!label || seen.has(label))
        return;
      seen.add(label);
      labels.push(label);
    };
    const bracketRegex = new RegExp(MENTION_BRACKET_REGEX);
