// src/server/class-reorder.ts
function reorderClasses(db2, projectId, updates) {
  if (!Array.isArray(updates) || !updates.length)
    throw new Error("\u8BF7\u9009\u62E9\u8981\u79FB\u52A8\u7684\u5206\u7C7B");
  return db2.transaction(() => {
    const classes = db2.query("SELECT id,parent_id FROM classes WHERE project_id IS ?").all(projectId);
    const parents = new Map(classes.map((item) => [item.id, item.parent_id]));
    const seen = new Set;
    const rows = updates.map((item) => {
      const id = typeof item?.id === "string" ? item.id : "";
      const parent = item?.parent_id == null || item.parent_id === "" ? null : item.parent_id;
      const order = Number(item?.sort_order);
      if (!parents.has(id) || seen.has(id))
        throw new Error("\u5206\u7C7B\u4E0D\u5B58\u5728\u3001\u91CD\u590D\u6216\u4E0D\u5C5E\u4E8E\u5F53\u524D\u5E94\u7528");
      if (parent !== null && (typeof parent !== "string" || !parents.has(parent)))
        throw new Error("\u76EE\u6807\u7236\u5206\u7C7B\u4E0D\u5C5E\u4E8E\u5F53\u524D\u5E94\u7528");
      if (item.sort_order == null || !Number.isFinite(order) || order < 0)
        throw new Error("\u5206\u7C7B\u987A\u5E8F\u65E0\u6548");
      seen.add(id);
      parents.set(id, parent);
      return { id, parent, order };
    });
    for (const { id } of rows) {
      const path = new Set;
      let current = id;
      while (current) {
        if (path.has(current))
          throw new Error("\u4E0D\u80FD\u5C06\u5206\u7C7B\u79FB\u52A8\u5230\u81EA\u8EAB\u6216\u5176\u540E\u4EE3\u4E0B\u9762");
        path.add(current);
        current = parents.get(current) || null;
      }
    }
    const statement = db2.prepare("UPDATE classes SET parent_id=?,sort_order=? WHERE id=? AND project_id IS ?");
    for (const row of rows)
      statement.run(row.parent, row.order, row.id, projectId);
    return rows.length;
  })();
}

// src/server/property-tail-suggestions.ts
function loadPropertyTailSuggestions(db2, propertyKeys, projectId, options = {}) {
  const placeholders = propertyKeys.map(() => "?").join(",");
  if (!placeholders)
    return null;
  const property = db2.query(`SELECT tail_ontology_id FROM properties WHERE id IN (${placeholders}) AND project_id IS ? LIMIT 1`).get(...propertyKeys, projectId);
  const tailId = String(property?.tail_ontology_id || "").trim();
  if (!tailId)
    return null;
  const tail = db2.query("SELECT id,name FROM ontologies WHERE id=? AND project_id IS ?").get(tailId, projectId);
  if (!tail)
    return { items: [], source: "tail_ontology", tailOntology: { id: tailId, name: tailId } };
  const query = String(options.query || "").trim();
  const limit = Math.max(1, Math.min(Number(options.limit) || 100, 100));
  const items = db2.query(`WITH RECURSIVE tail_types(id,name) AS (
    SELECT id,name FROM ontologies WHERE id=? AND project_id IS ?
    UNION
    SELECT o.id,o.name FROM ontologies o JOIN tail_types t ON o.parent_id=t.id WHERE o.project_id IS ?
  ) SELECT n.id,n.name AS label,n.description,n.type FROM nodes n
    WHERE n.project_id IS ? AND n.id <> ?
      AND EXISTS (SELECT 1 FROM tail_types t WHERE n.type=t.id OR lower(n.type)=lower(t.name))
      AND (?='' OR instr(lower(COALESCE(n.name,'')),lower(?))>0 OR instr(lower(COALESCE(n.description,'')),lower(?))>0)
    ORDER BY CASE WHEN n.type=? THEN 0 ELSE 1 END, n.name,n.id LIMIT ?
  `).all(tailId, projectId, projectId, projectId, String(options.excludeId || "").replace(/^entity\//, ""), query, query, query, tailId, limit);
  return { items, source: "tail_ontology", tailOntology: tail };
}

// src/server/routes/schema.ts
import { resolve as resolve9 } from "path";

// src/server/ontology-properties.ts
function loadOntologyProperties(db2, ontologyId, projectId, includeInherited = false) {
  return db2.query(`
    WITH RECURSIVE ancestors(id, parent_id) AS (
      SELECT id, parent_id FROM ontologies WHERE id = ? AND project_id IS ?
      UNION
      SELECT parent.id, parent.parent_id
      FROM ontologies parent JOIN ancestors child ON parent.id = child.parent_id
      WHERE ? = 1 AND parent.project_id IS ?
    )
    SELECT p.*, MAX(CASE WHEN op.ontology_id = ? THEN 1 ELSE 0 END) AS is_local
    FROM properties p
    JOIN ontology_properties op ON op.property_id = p.id
    JOIN ancestors a ON a.id = op.ontology_id
    WHERE p.project_id IS ? AND COALESCE(p.status, 'active') = 'active'
    GROUP BY p.id
    ORDER BY is_local DESC, p.name, p.id
  `).all(ontologyId, projectId, includeInherited ? 1 : 0, projectId, ontologyId, projectId);
}

