    return {};
  if (!criteria["\u4FE1\u606F\u4E0D\u8DB3"])
    criteria["\u4FE1\u606F\u4E0D\u8DB3"] = "\u73B0\u6709\u77E5\u8BC6\u6CA1\u6709\u8DB3\u591F\u8BC1\u636E\u4F5C\u51FA\u8BE5\u89D2\u5EA6\u7684\u5224\u65AD";
  return criteria;
