function selectBestDocByReply(docs, reply) {
  if (!docs || !docs.length)
    return null;
  try {
    if (reply && typeof reply === "string") {
      const matches = Array.from(reply.matchAll(/\[(\d+)\]/g)).map((m2) => parseInt(m2[1] || "0", 10)).filter((n) => Number.isFinite(n) && n >= 1 && n <= docs.length);
      if (matches.length) {
        const freq = {};
        for (const n of matches)
          freq[n] = (freq[n] || 0) + 1;
        const vals = Object.values(freq).map((v2) => Number(v2) || 0);
        const maxCount = vals.length ? Math.max(...vals) : 0;
        const candidates = Object.keys(freq).filter((k2) => freq[k2] === maxCount).map((k2) => parseInt(k2, 10));
        const chosenIdx = Math.min(...candidates) - 1;
        return docs[chosenIdx];
      }
    }
  } catch (e) {}
  try {
    return docs.reduce((a, b2) => (b2._score || 0) > (a._score || 0) ? b2 : a);
  } catch (e) {
    return docs[0];
  }
}
function buildGraphForSelectedSqlite(sel) {
  if (!sel || !sel._key)
    return { nodes: [], edges: [] };
  const key3 = sel._key;
  const centerId = key3;
  const nodes = [];
  const edges = [];
  try {
    const centerRow = db.query("SELECT * FROM nodes WHERE id = ?").get(centerId);
    if (centerRow) {
      const centerNode = formatNode(centerRow);
      nodes.push({
        data: {
          id: centerNode.id,
          label: centerNode.label_zh || centerNode.label || centerNode.name,
          root: true,
          image: Array.isArray(centerNode.images) && centerNode.images[0] || "",
          color: centerNode.color || ""
        }
      });
    }
    const attrs = db.query("SELECT * FROM attributes WHERE node_id = ? AND datatype = ?").all(centerId, "wikibase-entityid");
    const targets = new Set;
    for (const a of attrs) {
      try {
        const vals = JSON.parse(a.value || "null");
        const list3 = Array.isArray(vals) ? vals : vals ? [vals] : [];
        for (const v2 of list3) {
          const tidRaw = v2 && (v2.id || v2["entity-id"] || v2.target) ? v2.id || v2["entity-id"] || v2.target : null;
          if (tidRaw) {
            let tid = tidRaw;
            if (typeof tid === "string" && tid.startsWith("entity/"))
              tid = tid.replace("entity/", "");
            if (!tid)
              continue;
            targets.add(tid);
            edges.push({
              data: {
                id: `${a.id}:${tid}`,
                source: centerId,
                target: tid,
                label: a.key || a.property || ""
              }
            });
          }
        }
      } catch (e) {}
    }
    if (targets.size) {
      const placeholders = Array.from(targets).map(() => "?").join(",");
      const rows = db.query(`SELECT * FROM nodes WHERE id IN (${placeholders})`).all(...Array.from(targets));
      for (const r of rows) {
        const node = formatNode(r);
        nodes.push({
          data: {
            id: node.id,
            label: node.label_zh || node.label || node.name,
            image: Array.isArray(node.images) && node.images[0] || "",
            color: node.color || ""
          }
        });
      }
    }
  } catch (e) {
    console.warn("buildGraphForSelectedSqlite failed", e);
  }
  return { nodes, edges };
}
