  const mentionCount = dataObj && dataObj.mentions && typeof dataObj.mentions === "object" && !Array.isArray(dataObj.mentions) ? Object.keys(dataObj.mentions).length : 0;
  const richness = tags.length + images.length * 2 + covers.length * 2 + videos.length * 3 + (row.description ? 2 : 0) + (row.link ? 1 : 0) + (row.wiki_md ? 2 : 0) + mentionCount;
  const computedSize = Math.max(4, Math.min(18, 4 + richness * 0.45));
