  const commonsFilename = commonsFileMatch ? decodeURIComponent(commonsFileMatch[1] || "") : source.replace(/^File:/i, "");
  if (/^https:\/\//i.test(commonsFilename))
    return commonsFilename;
  if (!allowCommonsFilename && !IMAGE_FILE_PATTERN.test(commonsFilename))
    return "";
