  if (existing?.id)
    return String(existing.id);
  const id = `ontology/${crypto.randomUUID()}`;
  const order = projectId !== null ? db.query("SELECT COALESCE(MAX(sort_order), 0) AS value FROM ontologies WHERE project_id = ?").get(projectId) : db.query("SELECT COALESCE(MAX(sort_order), 0) AS value FROM ontologies WHERE project_id IS NULL").get();
  db.run("INSERT INTO ontologies (id, name, description, parent_id, project_id, sort_order, status) VALUES (?, ?, '', NULL, ?, ?, 'active')", [id, normalized, projectId, Number(order?.value || 0) + 1]);
