    if (!flow)
      throw new Error("\u6D41\u7A0B\u4E0D\u5B58\u5728\u6216\u65E0\u6743\u8BBF\u95EE");
    flow.nodes = this.db.query("SELECT * FROM cleaning_flow_nodes WHERE flow_id = ? ORDER BY rowid").all(id).map((n) => ({ id: n.id, type: n.type, x: n.x, y: n.y, config: JSON.parse(n.config_json) }));
