async function readWikidata(input) {
  const { query, limit } = wikidataQuery(input);
  const result = await executeSparqlRequest({ endpoint: process.env.WIKIDATA_SPARQL_ENDPOINT || "https://qlever.dev/api/wikidata", timeout: 20000 }, query);
  const rows = (result.rows || []).slice(0, limit).map((r) => Object.fromEntries(Object.entries(r).map(([k2, v2]) => [k2, v2?.value ?? ""])));
  return { columns: result.columns || Object.keys(rows[0] || {}), rows, sourceKey: "wikidata", query, truncated: (result.rows || []).length > limit };
}

// src/server/pipeline/http.ts
function createPipelineHandler(adminDb2, db2, getCurrentUser2, getProjectByIdentifier2) {
  let migrated = false;
  const publicPlan = (plan) => {
    const { changes, bindings, fingerprint, ...result } = plan;
    if (Array.isArray(result.branches))
      result.branches = result.branches.map(({ changes: changes2, bindings: bindings2, ...branch }) => branch);
    return result;
  };
  return async function handlePipelineRoutes(req, url, method) {
    if (!url.pathname.startsWith("/api/kb/pipeline/"))
      return null;
    const user = getCurrentUser2(req);
    if (!user)
      return Response.json({ error: "\u8BF7\u5148\u767B\u5F55" }, { status: 401 });
    const slug = url.searchParams.get("db");
    const project = slug && slug !== "app" ? getProjectByIdentifier2(slug) : null;
    if (slug && slug !== "app" && !project)
      return Response.json({ error: "\u5E94\u7528\u4E0D\u5B58\u5728" }, { status: 404 });
    if (user.role !== "admin" && (!project || !applicationPermissions(adminDb2, user, project).member))
      return Response.json({ error: "\u6279\u91CF\u5F55\u5165\u548C\u6E05\u6D17\u9700\u8981\u5F53\u524D\u5E94\u7528\u6210\u5458\u6743\u9650" }, { status: 403 });
    if (!migrated) {
      PipelineStore.migrate(adminDb2);
      migrated = true;
    }
    const store = new PipelineStore(adminDb2, project?.id || null, user.id);
    const engine = new CleaningEngine(store, db2, user);
    try {
      const path = url.pathname.slice("/api/kb/pipeline/".length);
      const body = method === "POST" ? await req.json() : {};
      if (path === "mysql" && method === "POST")
        return Response.json(await readMysql(body));
      if (path === "wikidata" && method === "POST")
        return Response.json(await readWikidata(body));
      if (path === "tables" && method === "GET")
        return Response.json({ items: store.listTables() });
      if (path === "tables" && method === "POST")
        return Response.json(store.saveTable(body));
      if (path.startsWith("tables/") && method === "GET")
        return Response.json(store.getTable(decodeURIComponent(path.slice(7))));
      if (path === "flows" && method === "GET")
        return Response.json({ items: store.listFlows() });
      if (path === "flows" && method === "POST")
        return Response.json(store.saveFlow(body));
      if (path.startsWith("flows/") && method === "GET")
        return Response.json(store.getFlow(decodeURIComponent(path.slice(6))));
      if (path === "properties" && method === "GET")
        return Response.json({ items: loadOntologyProperties(db2, url.searchParams.get("ontologyId") || "", store.projectId, true) });
      if (path === "runs" && method === "GET")
        return Response.json({ items: store.listRuns() });
      if (path.startsWith("runs/") && method === "GET") {
        const run = store.getRun(decodeURIComponent(path.slice(5)));
        return Response.json({ ...run, result: publicPlan(run.result) });
      }
      if (path === "run" && method === "POST") {
        if (!["preview", "full"].includes(body.mode))
          throw new Error("\u8FD0\u884C\u65B9\u5F0F\u65E0\u6548");
        const flow = store.getFlow(String(body.flowId || ""));
        const decisions = body.decisions || {};
        if (typeof decisions !== "object" || Array.isArray(decisions))
          throw new Error("\u5BF9\u9F50\u51B3\u7B56\u65E0\u6548");
        const plan = engine.plan(flow, body.mode, decisions);
        const run = store.saveRun(flow.id, body.mode, plan);
        return Response.json({ ...run, result: publicPlan(plan) });
      }
      if (path === "confirm" && method === "POST") {
        if (body.confirm !== true)
          throw new Error("\u8BF7\u786E\u8BA4\u6267\u884C\u7ED3\u679C\u540E\u518D\u4FDD\u5B58\u77E5\u8BC6\u5E93");
        const outputIds = body.outputIds === undefined ? undefined : body.outputIds;
        if (outputIds !== undefined && (!Array.isArray(outputIds) || outputIds.length > 24 || outputIds.some((id) => typeof id !== "string")))
          throw new Error("\u652F\u8DEF\u53C2\u6570\u65E0\u6548");
        const run = engine.confirm(String(body.runId || ""), outputIds);
        return Response.json({ ...run, result: publicPlan(run.result) });
      }
      return Response.json({ error: "\u63A5\u53E3\u4E0D\u5B58\u5728" }, { status: 404 });
    } catch (error) {
      return Response.json({ error: error.message || "\u64CD\u4F5C\u5931\u8D25" }, { status: 400 });
    }
  };
}

