    const maintainers = adminDb.query("SELECT u.id, u.username, u.display_name, m.created_at FROM knowledge_maintainers m JOIN users u ON u.id = m.user_id WHERE m.node_id = ? ORDER BY m.created_at, u.id").all(id);
    const requests = canManage ? adminDb.query("SELECT r.user_id, u.username, u.display_name, r.message, r.created_at FROM knowledge_maintenance_requests r JOIN users u ON u.id = r.user_id WHERE r.node_id = ? AND r.status = 'pending' ORDER BY r.created_at").all(id) : [];
    const ownRequest = user ? adminDb.query("SELECT status FROM knowledge_maintenance_requests WHERE node_id = ? AND user_id = ?").get(id, user.id) : null;
