  const mediaPath = path.replace(/\/{2,}/g, "/");
  if (/^\/static\/uploads\/(?:.*\/)?(node-images|node-videos|node-pdfs)\//i.test(mediaPath)) {
    const needle = `%${mediaPath}%`;
    const references = adminDb.query(`SELECT DISTINCT n.id FROM nodes n LEFT JOIN attributes a ON a.node_id = n.id
      WHERE n.images LIKE ? OR n.covers LIKE ? OR n.videos LIKE ? OR n.pdf LIKE ? OR n.data LIKE ? OR n.wiki_md LIKE ? OR a.value LIKE ? OR a.statement_json LIKE ?`).all(needle, needle, needle, needle, needle, needle, needle, needle);
    if (references.length ? !references.some((node) => !denied(node.id)) : !user)
      return response("\u9644\u4EF6\u4E0D\u5B58\u5728\u6216\u65E0\u6743\u8BBF\u95EE", 404);
    return null;
  }
  if (path.startsWith("/api/knowledge/")) {
    const id = decodeURIComponent(path.split("/")[3] || "");
    if (denied(id))
      return response("\u77E5\u8BC6\u4E0D\u5B58\u5728\u6216\u65E0\u6743\u8BBF\u95EE", 404);
    return null;
  }
  if (method === "GET") {
    if (path.startsWith("/api/kb/entry/tasks") && user?.role !== "admin") {
      const project2 = getProjectByIdentifier(url.searchParams.get("db") || "");
      if (!project2 || !applicationPermissions(adminDb, user, project2).member)
        return response("\u8BE5\u64CD\u4F5C\u9700\u8981\u5E94\u7528\u6210\u5458\u6743\u9650", 403);
    }
    if (["/api/kb/node", "/api/kb/node/graph", "/api/kb/node/attributes", "/api/kb/node/relations", "/api/wiki/page"].includes(path)) {
      const id = url.searchParams.get("id") || url.searchParams.get("entityId") || url.searchParams.get("entity_id");
      if (id && denied(id))
        return response("\u77E5\u8BC6\u4E0D\u5B58\u5728\u6216\u65E0\u6743\u8BBF\u95EE", 404);
    }
    return null;
  }
  if (!["POST", "PUT", "PATCH", "DELETE"].includes(method) || !path.startsWith("/api/kb/") && !path.startsWith("/api/wiki/") && !path.startsWith("/api/sparql/import"))
    return null;
