  if (path.startsWith("/api/kb/knowledge-"))
    return null;
  if (path.startsWith("/api/kb/upload-"))
    return null;
  if (["/api/kb/update_project", "/api/kb/delete_project"].includes(path)) {
    const project2 = adminDb.query("SELECT * FROM projects WHERE name=?").get(String(body.name || ""));
    const permission = applicationPermissions(adminDb, user, project2);
    return (path.endsWith("delete_project") ? permission.owner : permission.editSettings) ? null : response("\u65E0\u6743\u7BA1\u7406\u8BE5\u5E94\u7528", 403);
  }
  const check = (id, mode) => denied(id, mode) ? response(mode === "read" ? "\u77E5\u8BC6\u4E0D\u5B58\u5728\u6216\u65E0\u6743\u8BBF\u95EE" : "\u65E0\u6743\u4FEE\u6539\u8BE5\u77E5\u8BC6", mode === "read" ? 404 : 403) : null;
  if (path === "/api/kb/node/relation-order" && method === "POST")
    return check(body.id, "edit");
