  const savedKey = currentUser ? adminDb.query("SELECT jev_api_key FROM users WHERE id = ?").get(currentUser.id)?.jev_api_key : "";
  const apiKey = String(savedKey || "").trim();
  let body;
  try {
    body = await req.json();
  } catch {
    return json8({ error: "\u8BF7\u6C42\u5185\u5BB9\u5FC5\u987B\u662F JSON" }, 400);
  }
